
      function initNumberTrain() {
        const trains = document.querySelectorAll('.track_train_container');

        trains.forEach((train) => {
          const value = Math.max(0, Math.min(9, parseInt(train.dataset.number, 10)));
          const direction = (train.dataset.direction || 'up').toLowerCase();
          const track = train.querySelector('.number_track');

          if (!track) return;

          // Target posisi (setiap digit adalah 10% dari total track jika ada 10 box)
          // Namun paling aman pakai -10% * index karena CSS transform bekerja pada ukuran track itu sendiri
          const targetY = -(value * 10); 

          track.style.transition = 'none';

          let startY;
          if (direction === 'up') {
            // "Up" artinya angka datang dari bawah, jadi start harus lebih rendah (lebih negatif)
            startY = targetY - 30; // Mulai dari 3 digit di bawahnya
          } else {
            // "Down" artinya angka datang dari atas, jadi start harus lebih tinggi (lebih positif)
            startY = targetY + 30; // Mulai dari 3 digit di atasnya
          }

          // Batasi startY agar tidak keluar dari range 0% sampai -90% jika tidak ingin blank
          startY = Math.min(0, Math.max(-90, startY));

          track.style.transform = `translateY(${startY}%)`;

          // Force reflow
          track.offsetHeight;

          // Jalankan animasi
          track.style.transition = 'transform 1.2s cubic-bezier(0.23, 1, 0.32, 1)';
          
          requestAnimationFrame(() => {
            track.style.transform = `translateY(${targetY}%)`;
          });
        });
      }

      window.addEventListener('load', initNumberTrain);
